    where TDiffParam : DiffParam<TDiffGoo, TDiff>, new()
    where TDiffGoo : DiffGoo<TDiff>, new()
    where TDiff : Entity<TDiff>, new()
{
    protected ApplyDiffComponent() : base("", "", "") { }

    protected abstract string EntityName { get; }
